const excludedPrompts = new Set([
  "Marafon jangi qaysi ikki kuch o'rtasida bo'lib o'tgan?",
  "Somoniylar davlatining poytaxti qaysi shahar bo'lgan?"
])
groups[1][2] = groups[1][2].filter(item => !excludedPrompts.has(item[2])).slice(0, 75)
groups[2][2] = groups[2][2].filter(item => !excludedPrompts.has(item[2]))
groups[3][2] = groups[3][2].slice(0, 75)

if (groups.some(([sinf, bolim, items]) => items.length !== 75 || !topics[sinf][bolim])) {
  throw new Error('Savollar guruhi soni yoki mavzu xaritasi noto‘g‘ri.')
}

const questions = []

for (const [sinf, bolim, items] of groups) {
  for (const [mavzu, qiyinlik, savol, answer, distractor1, distractor2, izoh] of items) {
    const id = 10000 + questions.length
    const togriJavob = questions.length % 3
    const options = [distractor1, distractor2]
    options.splice(togriJavob, 0, answer)
    questions.push({
      id,
      sinf,
      bolim,
      mavzu,
      qiyinlik,
      savol,
      variantlar: options.map((option, index) => `${String.fromCharCode(65 + index)}) ${option}`),
      togriJavob,
      izoh
    })
  }
}

export const additionalQuestions56 = questions
